**Score:** 1.000

// #399: stand-in answers from saved, made-up responses and never leaves the process; live reaches OLT's TMS with its key.
export type TmsSettings =
  {mode: 'stand-in'} | {mode: 'live'; client: TmsClientConfig; apiKey: string};

---

**Score:** 0.985

// FR-040, FR-041: the key is read here once, and only live needs it; the stand-in never leaves the process.
function readTmsSettings(env: NodeJS.ProcessEnv): TmsSettings {
  enforceExists(
    env.TMS_MODE,
    'TMS_MODE environment variable is required. Please set it in your .env file.'
  );
  if (env.TMS_MODE === 'live') return readLiveTms(env);
  if (env.TMS_MODE === 'stand-in') return {mode: 'stand-in'};
  throw new Error('TMS_MODE must be stand-in or live.');
}

